companionBundle.script:
const root = document.getElementById('app');

root.innerHTML = `
  <main class="browser-shell">
    <form class="address-row" id="address-form">
      <button type="button" class="icon" id="back" aria-label="Zurück">‹</button>
      <span class="connection" id="connection" title="PC wird verbunden"></span>
      <input id="address" inputmode="url" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Adresse oder Suche" />
      <button type="button" class="icon menu-button" id="menu-button" aria-label="Browser-Menü">•••</button>
      <div class="menu hidden" id="menu">
        <button type="button" id="forward">Vor</button>
        <button type="button" id="reload">Neu laden</button>
        <button type="button" id="rotate">Ansicht drehen</button>
        <button type="button" id="copy">Auswahl kopieren</button>
      </div>
    </form>
    <section class="viewport" id="viewport">
      <canvas id="screen" aria-label="Ansicht des Browsers auf dem PC"></canvas>
      <div class="remote-cursor" id="remote-cursor" aria-hidden="true"></div>
      <div class="empty" id="empty">
        <div class="pulse"></div>
        <strong>Browser auf deinem PC</strong>
        <span id="status">wird verbunden …</span>
      </div>
      <div class="mode-switch" role="group" aria-label="Bedienungsart">
        <button type="button" class="active" id="direct-mode">Direkt</button>
        <button type="button" id="mouse-mode">Maus</button>
      </div>
    </section>
    <textarea id="key-input" aria-label="Text in den PC-Browser eingeben" autocapitalize="sentences" autocomplete="off"></textarea>
  </main>
`;

const address = document.getElementById('address');
const canvas = document.getElementById('screen');
const context = canvas.getContext('2d', { alpha: false });
canvas.width = 0;
canvas.height = 0;
const viewport = document.getElementById('viewport');
const empty = document.getElementById('empty');
const status = document.getElementById('status');
const connection = document.getElementById('connection');
const keyInput = document.getElementById('key-input');
const menu = document.getElementById('menu');
const remoteCursor = document.getElementById('remote-cursor');
if (!teydra.orientation?.toggle) document.getElementById('rotate').hidden = true;
let latest = null;
let revision = null;
let stopped = false;
let drag = null;
let mode = 'direct';
let localCursor = { x: 640, y: 360, actor: 'human' };
let typedTail = Promise.resolve();
let controlTail = Promise.resolve();

function normalizedUrl(value) {
  const clean = value.trim();
  if (!clean) return null;
  if (/^https?:\/\//i.test(clean)) return clean;
  if (/^[a-z0-9.-]+\.[a-z]{2,}(?:[/:?#]|$)/i.test(clean)) return `https://${clean}`;
  return `https://www.google.com/search?q=${encodeURIComponent(clean)}`;
}

async function applySnapshot(snapshot) {
  if (!snapshot || typeof snapshot !== 'object') return false;
  latest = snapshot;
  if (snapshot.frame && !await applyFrame(snapshot.frame)) return false;
  if (typeof snapshot.url === 'string' && document.activeElement !== address && snapshot.url !== 'about:blank') {
    address.value = snapshot.url;
  }
  document.getElementById('back').disabled = !snapshot.canGoBack;
  document.getElementById('forward').disabled = !snapshot.canGoForward;
  if (snapshot.cursor) localCursor = snapshot.cursor;
  placeCursor();
  connection.classList.add('online');
  connection.title = 'PC verbunden';
  if (canvas.width > 0) empty.classList.add('hidden');
  return true;
}

async function applyFrame(frame) {
  if (frame.protocol !== 1 || !Array.isArray(frame.steps)) return false;
  if (!frame.reset && revision !== frame.baseRevision) {
    revision = null;
    return false;
  }
  if (frame.reset) {
    canvas.width = frame.width;
    canvas.height = frame.height;
    context.fillStyle = '#ffffff';
    context.fillRect(0, 0, canvas.width, canvas.height);
  }
  for (const step of frame.steps) {
    if (step.type === 'move') applyMove(step);
    if (step.type === 'paint') applyPaint(step);
    if (step.type === 'image') await applyImage(step);
  }
  revision = frame.revision;
  return true;
}

function applyMove(step) {
  const copy = document.createElement('canvas');
  copy.width = step.width;
  copy.height = step.height;
  copy.getContext('2d', { alpha: false }).drawImage(
    canvas,
    step.sourceX, step.sourceY, step.width, step.height,
    0, 0, step.width, step.height,
  );
  context.drawImage(copy, step.targetX, step.targetY);
}

function applyPaint(step) {
  if (!Array.isArray(step.boxes)) return;
  for (const box of step.boxes) {
    if (!Array.isArray(box) || box.length !== 5) continue;
    const [x, y, width, height, color] = box;
    context.fillStyle = `#${Number(color).toString(16).padStart(6, '0')}`;
    context.fillRect(x, y, width, height);
  }
}

function applyImage(step) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => {
      context.drawImage(image, step.x, step.y, step.width, step.height);
      resolve();
    };
    image.onerror = () => reject(new Error('Ein Browser-Bildausschnitt war beschädigt.'));
    image.src = `data:${step.mimeType};base64,${step.data}`;
  });
}

function applyFailure(error) {
  connection.classList.remove('online');
  connection.title = 'PC getrennt';
  status.textContent = error instanceof Error ? error.message : 'Der PC antwortet nicht.';
  if (canvas.width === 0) empty.classList.remove('hidden');
}

function control(actionId, input = {}) {
  const result = controlTail.then(async () => {
    if (stopped) return null;
    try {
      const snapshot = await teydra.query(actionId, { ...input, frameRevision: revision });
      await applySnapshot(snapshot);
      return snapshot;
    } catch (error) {
      applyFailure(error);
      return null;
    }
  });
  controlTail = result.then(() => undefined, () => undefined);
  return result;
}

async function streamFrames() {
  while (!stopped) {
    try {
      const action = revision === null ? 'browser.start' : 'browser.snapshot';
      const snapshot = await teydra.query(action, { frameRevision: revision });
      await applySnapshot(snapshot);
    } catch (error) {
      applyFailure(error);
      await wait(1_000);
    }
  }
}

document.getElementById('address-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const url = normalizedUrl(address.value);
  if (!url) return;
  address.blur();
  await control('browser.navigate', { url });
});

document.getElementById('back').addEventListener('click', () => control('browser.back'));
document.getElementById('forward').addEventListener('click', () => closeMenu(control('browser.forward')));
document.getElementById('reload').addEventListener('click', () => closeMenu(control('browser.reload')));
document.getElementById('menu-button').addEventListener('click', () => menu.classList.toggle('hidden'));
document.getElementById('rotate').addEventListener('click', async () => {
  menu.classList.add('hidden');
  try { await teydra.orientation?.toggle?.(); } catch (error) { applyFailure(error); }
});
document.getElementById('copy').addEventListener('click', async () => {
  menu.classList.add('hidden');
  try {
    if (!latest?.selection) throw new Error('Im Browser ist kein Text ausgewählt.');
    await teydra.clipboard.write(latest.selection);
  } catch (error) {
    status.textContent = error instanceof Error ? error.message : 'Kopieren wurde nicht erlaubt.';
  }
});

document.getElementById('direct-mode').addEventListener('click', () => setMode('direct'));
document.getElementById('mouse-mode').addEventListener('click', () => setMode('mouse'));

canvas.addEventListener('pointerdown', (event) => {
  canvas.setPointerCapture(event.pointerId);
  const point = remotePoint(event);
  drag = { id: event.pointerId, clientX: event.clientX, clientY: event.clientY, point, moved: false };
});
canvas.addEventListener('pointermove', (event) => {
  if (!drag || drag.id !== event.pointerId) return;
  const dx = event.clientX - drag.clientX;
  const dy = event.clientY - drag.clientY;
  if (Math.abs(dx) + Math.abs(dy) > 10) drag.moved = true;
  if (mode === 'mouse') {
    const box = canvas.getBoundingClientRect();
    localCursor = {
      x: clamp(drag.point.x + dx / box.width * canvas.width, 0, canvas.width),
      y: clamp(drag.point.y + dy / box.height * canvas.height, 0, canvas.height),
      actor: 'human',
    };
    placeCursor();
  }
});
canvas.addEventListener('pointerup', async (event) => {
  if (!drag || drag.id !== event.pointerId || !latest) return;
  const start = drag;
  drag = null;
  if (mode === 'mouse') {
    if (start.moved) {
      await control('browser.move', { x: localCursor.x, y: localCursor.y });
      return;
    }
    const snapshot = await control('browser.pointer', { x: localCursor.x, y: localCursor.y });
    if (snapshot?.acceptsText) keyInput.focus();
    return;
  }
  const point = remotePoint(event);
  if (start.moved) {
    const box = canvas.getBoundingClientRect();
    await control('browser.scroll', {
      x: point.x,
      y: point.y,
      deltaX: (start.clientX - event.clientX) / box.width * canvas.width,
      deltaY: (start.clientY - event.clientY) / box.height * canvas.height,
    });
  } else {
    const snapshot = await control('browser.pointer', point);
    if (snapshot?.acceptsText) keyInput.focus();
  }
});

keyInput.addEventListener('input', () => {
  const text = keyInput.value;
  keyInput.value = '';
  if (!text) return;
  typedTail = typedTail.then(() => control('browser.type', { text }));
});
keyInput.addEventListener('keydown', (event) => {
  if (!['Enter', 'Backspace', 'Tab', 'Escape', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.key)) return;
  event.preventDefault();
  typedTail = typedTail.then(() => control('browser.key', { key: event.key }));
});

function setMode(next) {
  mode = next;
  document.getElementById('direct-mode').classList.toggle('active', next === 'direct');
  document.getElementById('mouse-mode').classList.toggle('active', next === 'mouse');
  remoteCursor.classList.toggle('visible', next === 'mouse' || localCursor.actor === 'ai');
  placeCursor();
}

function placeCursor() {
  if (!canvas.width) return;
  const canvasBox = canvas.getBoundingClientRect();
  const viewportBox = viewport.getBoundingClientRect();
  const left = canvasBox.left - viewportBox.left + localCursor.x / canvas.width * canvasBox.width;
  const top = canvasBox.top - viewportBox.top + localCursor.y / canvas.height * canvasBox.height;
  remoteCursor.style.transform = `translate(${left}px, ${top}px)`;
  remoteCursor.classList.toggle('ai', localCursor.actor === 'ai');
  remoteCursor.classList.toggle('visible', mode === 'mouse' || localCursor.actor === 'ai');
}

function remotePoint(event) {
  const box = canvas.getBoundingClientRect();
  return {
    x: clamp((event.clientX - box.left) / box.width * canvas.width, 0, canvas.width),
    y: clamp((event.clientY - box.top) / box.height * canvas.height, 0, canvas.height),
  };
}

function closeMenu(promise) {
  menu.classList.add('hidden');
  return promise;
}

function clamp(value, minimum, maximum) {
  return Math.max(minimum, Math.min(maximum, value));
}

function wait(milliseconds) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

window.addEventListener('resize', placeCursor);
window.addEventListener('beforeunload', () => { stopped = true; });
teydra.ready(streamFrames);

companionBundle.style:
:root {
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #090b0b;
  color: #f5f7f6;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body, #app { width: 100%; height: 100%; margin: 0; overflow: hidden; }
button, input, textarea { font: inherit; }
button { color: inherit; }
.browser-shell { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); background: #090b0b; }
.address-row {
  position: relative; z-index: 4; display: grid; grid-template-columns: 34px 8px minmax(0, 1fr) 38px;
  align-items: center; gap: 7px; padding: 7px 8px; border-bottom: 1px solid #202a27; background: #101413;
}
.address-row button { appearance: none; border: 0; border-radius: 10px; background: transparent; min-height: 36px; }
.address-row button:active { background: #26312e; transform: scale(.97); }
.address-row button:disabled { opacity: .26; }
.address-row .icon { font-size: 24px; line-height: 1; }
.menu-button { font-size: 15px !important; font-weight: 800; letter-spacing: 1px; }
.connection { width: 7px; height: 7px; border-radius: 50%; background: #6c7471; box-shadow: 0 0 0 2px #1d2321; }
.connection.online { background: #5bd5ad; box-shadow: 0 0 0 2px #143d30; }
#address {
  width: 100%; min-width: 0; min-height: 36px; border: 1px solid #293632; border-radius: 11px;
  outline: none; padding: 0 11px; background: #080a09; color: #edf5f2; font-size: 13px;
}
#address:focus { border-color: #40b995; box-shadow: 0 0 0 2px #174638; }
.menu {
  position: absolute; top: 50px; right: 8px; width: 178px; display: grid; padding: 6px;
  border: 1px solid #33423d; border-radius: 13px; background: #171d1b; box-shadow: 0 12px 34px #0009;
}
.menu.hidden { display: none; }
.menu button { min-height: 39px; padding: 0 11px; text-align: left; font-size: 13px; }
.viewport {
  position: relative; min-height: 0; display: grid; place-items: center; overflow: hidden;
  background: #151817; touch-action: none;
}
#screen {
  display: block; width: 100%; height: auto; max-height: 100%; aspect-ratio: 16 / 9;
  object-fit: contain; background: #fff; user-select: none; -webkit-user-select: none;
}
.empty {
  position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 9px;
  padding: 30px; color: #e8efed; text-align: center; background: radial-gradient(circle at 50% 43%, #17241f, #0d1110 55%);
}
.empty.hidden { display: none; }
.empty span { max-width: 280px; color: #8d9d98; font-size: 13px; line-height: 1.45; }
.pulse { width: 38px; height: 38px; margin-bottom: 7px; border: 2px solid #2b6d59; border-top-color: #70dfbd; border-radius: 50%; animation: turn 1s linear infinite; }
.mode-switch {
  position: absolute; right: 10px; bottom: calc(10px + env(safe-area-inset-bottom)); display: flex;
  padding: 3px; border: 1px solid #ffffff1f; border-radius: 12px; background: #0d1210dd; backdrop-filter: blur(12px);
}
.mode-switch button { appearance: none; min-height: 30px; padding: 0 10px; border: 0; border-radius: 9px; background: transparent; color: #a5b0ac; font-size: 11px; font-weight: 750; }
.mode-switch button.active { background: #2a3733; color: #f3f8f6; }
.remote-cursor {
  position: absolute; left: 0; top: 0; z-index: 3; width: 15px; height: 21px; opacity: 0; pointer-events: none;
  transform-origin: 0 0; transition: opacity .12s;
}
.remote-cursor::before {
  content: ''; position: absolute; inset: 0; clip-path: polygon(0 0, 0 80%, 26% 60%, 44% 100%, 61% 91%, 42% 54%, 78% 54%);
  background: #f7fbfa; filter: drop-shadow(0 1px 1px #000) drop-shadow(0 0 1px #000);
}
.remote-cursor.ai::after { content: 'KI'; position: absolute; left: 12px; top: 12px; padding: 2px 4px; border-radius: 5px; background: #10a37f; color: white; font-size: 8px; font-weight: 900; }
.remote-cursor.visible { opacity: 1; }
#key-input { position: fixed; left: 50%; bottom: 1px; width: 2px; height: 2px; opacity: .01; resize: none; }
@keyframes turn { to { transform: rotate(360deg); } }

@media (orientation: landscape) {
  .address-row { padding-top: max(5px, env(safe-area-inset-top)); padding-left: max(8px, env(safe-area-inset-left)); padding-right: max(8px, env(safe-area-inset-right)); }
  .mode-switch { right: max(10px, env(safe-area-inset-right)); }
}
